const cds = require('../../../cds')
const { path, sh: $ } = cds.utils
const { renderAndCopy } = require('../../template')
const { merge } = require('../../merge')
const { readProject } = require('../../projectReader')

module.exports = class ReactTemplate extends require('../../plugin') {

  options() {
    return {
      'into': {
        type: 'string',
        short: 'i',
        help: `Name of the app folder in 'app/'. Example: 'catalog' → 'app/catalog'. Omit for a single-UI scenario where the Vite app sits directly in 'app/'.`
      },
      'ts': {
        type: 'boolean',
        help: 'Override the inferred project type and generate a TypeScript app.'
      },
      'js': {
        type: 'boolean',
        help: 'Override the inferred project type and generate a JavaScript app.'
      }
    }
  }

  static help() {
    return 'user interface for React'
  }

  async run() {
    const into = cds.cli.options.into
    const isRoot = !into || into === '.' || into === ''
    const app = isRoot ? path.basename(cds.root) : into
    const target = isRoot ? cds.env.folders.app : path.join(cds.env.folders.app, into)
    const modelsPath = path.relative(target, '@cds-models').split(path.sep).join('/')
    if (cds.cli.options.ts && cds.cli.options.js) throw "options '--ts' and '--js' cannot be combined"
    const typescript = cds.cli.options.ts || !cds.cli.options.js && readProject().isTypescript
    await renderAndCopy(path.join(__dirname, 'files'), target, {
      app,
      typescript,
      extension: typescript ? 'ts' : 'js',
      jsxExtension: typescript ? 'tsx' : 'jsx',
      isJava: cds.env['project-nature'] === 'java',
      isRoot,
      base: './',
      archiveName: isRoot ? app : into,
      modelsPath,
    })
    if (typescript) await renderAndCopy(path.join(__dirname, 'typescript'), target, { modelsPath })
    await merge({ scripts: { watch: 'cds watch --exclude app/' }, workspaces: ['app/*'] }).into('package.json')
    if (typescript) await merge({ compilerOptions: { noEmit: true }, exclude: ['app'] }).into('tsconfig.json')
    const root = cds.cli.command === 'init' ? cds.cli.argv[0] : cds.root
    await $`npm i --prefix ${root}`
  }
}
